#!/usr/bin/env python3
"""Print line, word and character counts for files, like wc.

Lines are counted as newline characters (as wc does), words are runs of
non-whitespace, and characters are Unicode code points of the file decoded
as UTF-8. Invalid UTF-8 bytes count as one character each.
"""

import argparse
import json
import sys

FIELDS = ("lines", "words", "chars")


def count_text(text):
    """Return (lines, words, chars) for a string."""
    return text.count("\n"), len(text.split()), len(text)


def count_file(path):
    """Return (lines, words, chars) for the file at path."""
    # newline="" keeps \r\n intact so carriage returns are counted.
    with open(path, encoding="utf-8", errors="replace", newline="") as f:
        return count_text(f.read())


def format_table(rows):
    """Format (name, counts) rows as right-aligned columns."""
    width = max(len(str(n)) for _, counts in rows for n in counts)
    return [
        " ".join(f"{n:>{width}}" for n in counts) + f" {name}"
        for name, counts in rows
    ]


def main(argv=None):
    parser = argparse.ArgumentParser(
        prog="wcount",
        description="Print line, word and character counts for each file.",
    )
    parser.add_argument("files", nargs="+", metavar="FILE", help="files to count")
    parser.add_argument("--json", action="store_true", help="print the counts as JSON")
    args = parser.parse_args(argv)

    status = 0
    results = []
    for name in args.files:
        try:
            results.append((name, count_file(name)))
        except OSError as e:
            print(f"wcount: {name}: {e.strerror or e}", file=sys.stderr)
            status = 1

    total = tuple(sum(counts[i] for _, counts in results) for i in range(len(FIELDS)))

    if args.json:
        data = {
            "files": [{"file": name, **dict(zip(FIELDS, counts))} for name, counts in results],
            "total": dict(zip(FIELDS, total)),
        }
        print(json.dumps(data, indent=2))
    else:
        rows = list(results)
        if len(rows) > 1:
            rows.append(("total", total))
        if rows:
            print("\n".join(format_table(rows)))

    return status


if __name__ == "__main__":
    sys.exit(main())

